function esc(s=''){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function person(id){return db.people.find(p=>p.id===id)}function task(id){return db.tasks.find(t=>t.id===id)}function date(s){return s?new Date(s+'T00:00:00').toLocaleDateString('zh-TW',{month:'numeric',day:'numeric',weekday:'short'}):'—'}function time(t){return `${t.start}–${t.end}`}function overlaps(a,b){return a.date===b.date&&a.start<b.end&&b.start<a.end}function assigned(t){return(t.assigned||[]).map(person).filter(Boolean)}function shortage(t){return Math.max(0,Number(t.need||0)-(t.assigned||[]).length)}function status(t){const s=t.status||'規劃中';return `<span class="badge ${s==='已完成'?'ok':s==='進行中'?'short':''}">${esc(s)}</span>`}function staffing(t){const gap=Number(t.need||0)-(t.assigned||[]).length;return gap>0?`<span class="badge short">缺 ${gap} 人</span>`:gap<0?`<span class="badge conflict">超額 ${Math.abs(gap)} 人</span>`:`<span class="badge ok">已額滿</span>`}function taskConflicts(t){const found=[];for(const pid of (t.assigned||[])){for(const other of conflicts(pid,t)){if(!found.some(x=>x.pid===pid&&x.task.id===other.id))found.push({pid,person:person(pid),task:other})}}return found}function leaderOverlapTasks(t){return t.leaderId?db.tasks.filter(x=>x.id!==t.id&&x.leaderId===t.leaderId&&overlaps(x,t)):[]}function leaderOverlapMarkup(t){const list=leaderOverlapTasks(t);return list.length?`<div class="leader-overlap-warning"><b>⚠ 此負責人同時負責其他工作</b>${list.map(x=>`<div>${esc(x.name)}｜${esc(x.date.slice(5).replace('-','/'))} ${esc(time(x))}</div>`).join('')}</div>`:''}function conflicts(pid,t,exclude=t.id){return db.tasks.filter(x=>x.id!==exclude&&(x.assigned||[]).includes(pid)&&overlaps(x,t))}
