function parseCsvRows(text){text=text.replace(/^\ufeff/,'');const first=(text.split(/\r?\n/)[0]||'');let delimiter=',',semi=0,comma=0,quoted=false;for(let i=0;i<first.length;i++){if(first[i]==='"')quoted=!quoted;else if(!quoted&&first[i]===';')semi++;else if(!quoted&&first[i]===',')comma++}if(semi>comma)delimiter=';';const rows=[];let row=[],value='',quotedField=false,line=1,rowLine=1;for(let i=0;i<text.length;i++){const ch=text[i];if(quotedField){if(ch==='"'&&text[i+1]==='"'){value+='"';i++}else if(ch==='"')quotedField=false;else value+=ch;continue}if(ch==='"'){quotedField=true;continue}if(ch===delimiter){row.push(value);value='';continue}if(ch==='\r'||ch==='\n'){row.push(value);if(row.some(x=>String(x).trim()!==''))rows.push({line:rowLine,values:row});row=[];value='';if(ch==='\r'&&text[i+1]==='\n')i++;line++;rowLine=line;continue}value+=ch}row.push(value);if(row.some(x=>String(x).trim()!==''))rows.push({line:rowLine,values:row});return rows}
function excelSerialDate(value){const n=Number(value);if(!Number.isFinite(n)||n<1||n>2958465)return null;const d=new Date(Date.UTC(1899,11,30)+Math.floor(n)*86400000);return d.toISOString().slice(0,10)}
function normalizeWorkDate(value){if(typeof value==='number'||/^\d{4,6}(?:\.0+)?$/.test(String(value).trim())){const serial=excelSerialDate(value);if(serial)return serial}const m=String(value??'').trim().match(/^(\d{4})[-/.](\d{1,2})[-/.](\d{1,2})$/);if(!m)return null;const y=Number(m[1]),mo=Number(m[2]),d=Number(m[3]),check=new Date(Date.UTC(y,mo-1,d));if(check.getUTCFullYear()!==y||check.getUTCMonth()!==mo-1||check.getUTCDate()!==d)return null;return `${String(y).padStart(4,'0')}-${String(mo).padStart(2,'0')}-${String(d).padStart(2,'0')}`}
function normalizeWorkTime(value){if(typeof value==='number'||/^0(?:\.\d+)?$/.test(String(value).trim())){const n=Number(value);if(Number.isFinite(n)&&n>=0&&n<1){const minutes=Math.min(1439,Math.round(n*1440)),h=Math.floor(minutes/60),m=minutes%60;return `${String(h).padStart(2,'0')}:${String(m).padStart(2,'0')}`}}const m=String(value??'').trim().match(/^(\d{1,2}):(\d{2})(?::(\d{2}))?$/);if(!m)return null;const h=Number(m[1]),min=Number(m[2]),sec=Number(m[3]||0);if(h>23||min>59||sec!==0)return null;return `${String(h).padStart(2,'0')}:${String(min).padStart(2,'0')}`}
