function applyFilters(){if(page==='tasks'){applyTaskFilters();return}let d=$('#filterDate')?.value||'',tm=$('#filterTime')?.value||'',tn=$('#filterTask')?.value||'',ln=$('#filterLeader')?.value||'';let list=db.tasks.filter(t=>(!d||t.date===d)&&(!tm||(t.start<=tm&&t.end>tm))&&(!tn||t.name===tn)&&(!ln||String(t.leaderId||'')===ln));const tbody=content.querySelector('tbody');if(tbody)tbody.innerHTML=rows(list)}
function csvCell(v){return '"'+String(v??'').replace(/"/g,'""')+'"'}function download(filename,text){const url=URL.createObjectURL(new Blob(['\ufeff'+text],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=filename;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}function downloadJson(filename,text){const url=URL.createObjectURL(new Blob([text],{type:"application/json;charset=utf-8"})),a=document.createElement("a");a.href=url;a.download=filename;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}function resetWorkData(){if(!window.confirm("確定要清除所有測試資料嗎？"))return;if(!window.confirm("第二次確認：將清除全部服務人員、工作、排班及活動測試資料。這不會刪除已下載的備份檔。要繼續嗎？"))return;const backup=JSON.stringify(db,null,2);downloadJson("福祿圓滿_清除前完整備份_"+new Date().toISOString().replace(/[:.]/g,"-")+".json",backup);db={event:{name:"",start:"",end:"",description:""},people:[],tasks:[]};pendingWorkImport=null;const input=$("#workImportInput"),peopleInput=$("#fileInput");if(input)input.value="";if(peopleInput)peopleInput.value="";MU.forceReplace=true;save();toast("測試資料已全部清除；服務人員名單與工作均為空白")}function exportTasks(){const head=['日期','時間','工作','地點','需求','已排','缺額','主要負責人','已安排人員','狀態'];const lines=db.tasks.map(t=>[t.date,time(t),t.name,t.place,t.need,t.assigned.length,shortage(t),taskLeaderLabel(t),assigned(t).map(p=>personLabel(p.id)).join('、'),shortage(t)?'缺人':'已完成'].map(csvCell).join(','));download('福祿圓滿_完整排班.csv',[head.map(csvCell).join(','),...lines].join('\r\n'))}
$('#workImportInput').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{const records=/\.xlsx$/i.test(file.name)?await parseXlsxRows(file):parseCsvRows(await file.text());buildWorkPreview(records);pendingWorkImport.filename=file.name;render()}catch(err){pendingWorkImport={filename:file.name,rows:[],headerErrors:[`無法讀取檔案：${err.message||'格式錯誤'}`]};render()}e.target.value=''});
$('#fileInput').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;const text=await file.text(),lines=text.replace(/^\ufeff/,'').split(/\r?\n/).filter(Boolean).map(line=>{let out=[],v='',q=false;for(let i=0;i<line.length;i++){if(line[i]==='"'&&line[i+1]==='"'&&q){v+='"';i++}else if(line[i]==='"')q=!q;else if(line[i]===','&&!q){out.push(v);v=''}else v+=line[i]}out.push(v);return out});const h=lines.shift().map(x=>x.trim()),idx=(...alts)=>h.findIndex(x=>alts.includes(x)),iId=idx('編號','學員編號','ID'),iName=idx('姓名','學員姓名','名字');if(iName<0){toast('找不到「姓名」欄，請確認 CSV 標題列');e.target.value='';return}let n=0;for(const r of lines){if(!r[iName]?.trim())continue;let id=iId>=0?r[iId].trim():'';let p=id?person(id):null;const record={id:id||'P'+Date.now()+n,name:r[iName].trim(),gender:r[idx('性別')]||'',phone:r[idx('電話','手機')]||'',note:r[idx('備註')]||'',active:!['否','停用','0','false'].includes((r[idx('是否啟用','狀態')]||'是').trim().toLowerCase())};if(p)Object.assign(p,record);else db.people.push(record);n++}peopleSort='id-asc';save();toast(`已匯入 ${n} 位服務人員`);e.target.value=''});
$('#resetDataBtn').onclick=()=>resetWorkData();$('#backupBtn').onclick=()=>download('福祿圓滿_完整資料備份.json',JSON.stringify(db,null,2));$('#restoreBtn').onclick=()=>$('#backupRestoreInput').click();$('#backupRestoreInput').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{const parsed=JSON.parse(await file.text());if(!parsed||typeof parsed!=='object'||!Array.isArray(parsed.people)||!Array.isArray(parsed.tasks)||!parsed.event||typeof parsed.event!=='object')throw new Error('檔案不是有效的福祿圓滿完整資料備份');if(!confirm('還原會以備份內容取代所有人共用的活動、服務人員、工作及排班資料。建議先匯出目前資料備份。確定要繼續嗎？'))return;db={event:parsed.event,people:parsed.people,tasks:parsed.tasks};normalizePeopleReferences(db);MU.forceReplace=true;save();toast('完整資料已還原')}catch(err){alert('無法還原資料：'+(err.message||'請確認 JSON 備份檔格式'))}finally{e.target.value=''}});$('#settingsBtn').onclick=()=>{editId=null;$('#modalEyebrow').textContent='活動設定';$('#modalTitle').textContent='活動資料';$('#form').dataset.kind='event';$('#formBody').innerHTML=`${field('活動名稱','name',db.event.name)}${field('活動開始日期','start',db.event.start,'date')}${field('活動結束日期','end',db.event.end,'date')}${field('活動說明','description',db.event.description,'textarea',true)}`;$('#modal').showModal()};$('#form').addEventListener('submit',e=>{if(e.currentTarget.dataset.kind==='event'){e.preventDefault();db.event=Object.fromEntries(new FormData(e.currentTarget).entries());db.event.id=db.event.id||'E001';$('#modal').close();save();toast('活動資料已更新')}});
// Excel 需求單讀取（原版呼叫了這個函式但沒有定義）。
async function parseXlsxRows(file){if(!window.ExcelJS?.Workbook)throw new Error('Excel 元件尚未載入，請確認這台裝置可以上網');const workbook=new ExcelJS.Workbook();await workbook.xlsx.load(await file.arrayBuffer());const sheet=workbook.worksheets[0];if(!sheet)return[];const pad=n=>String(n).padStart(2,'0'),cellValue=cell=>{let v=cell.value;if(v&&typeof v==='object'&&!(v instanceof Date)){if('result' in v)v=v.result;else if(Array.isArray(v.richText))v=v.richText.map(x=>x.text).join('');else if('text' in v)v=v.text}if(v instanceof Date)return v.getUTCFullYear()<=1900?`${pad(v.getUTCHours())}:${pad(v.getUTCMinutes())}`:`${v.getUTCFullYear()}-${pad(v.getUTCMonth()+1)}-${pad(v.getUTCDate())}`;return v??''};const rows=[];sheet.eachRow({includeEmpty:false},(row,line)=>{const values=[];for(let c=1;c<=sheet.columnCount;c++)values.push(cellValue(row.getCell(c)));if(values.some(x=>String(x).trim()!==''))rows.push({line,values})});return rows}
